draw(((-6,0)--(6,0)));
label("$12$",(0,0),S);
draw(((-6,-0.6)--(-0.6,-0.6)),BeginArrow);
draw(((0.6,-0.6)--(6,-0.6)),EndArrow);
draw(((-6,0)--(0,6)));
draw(((0,6)--(6,0)));
draw(((0,0)--(0,6)),dashed);
label("$6$",(0,2.5),E);
