draw(B--A);
draw(B--C);
draw(B--Y);
draw(T--X,dashed);
draw(T--D,dashed);
draw(T--Z,dashed);

label("$X$", (C + D)/2, N);
label("$Y$", (B + C)/2, SE);
label("$Z$", (B + Y)/2, W);
[/asy]

